import { describe, expect, it } from 'vitest'
import { decodeFunctionData, encodeFunctionResult } from 'viem'
import {
  ORIGINAL_GHO,
  UMBRELLA_GHO_ROUTE,
  UMBRELLA_STKGHO,
  VERIFIED_STKGHO_IMPLEMENTATION,
} from '@/lib/carry/umbrellaGhoExit'
import {
  UMBRELLA_GHO_NATIVE_ABI,
  umbrellaGhoNativeCapacityReadPlan,
  umbrellaGhoNativeCapacityEntitlementReadPlan,
  replayUmbrellaGhoNativeCapacityFact,
  selectedUmbrellaGhoNativeCapacityFact,
  projectUmbrellaGhoNativeHeader,
  type UmbrellaGhoNativeCapacityBinding,
} from '@/lib/carry/umbrellaGhoNativeCapacity'

// Synthetic native getter observations; no acquisition/ownership/authentication authority.
// Only runtime bytes are copied from the actual 66-read current capture's raw native code responses.
// Capture: umbrella-gho-current-native-2026-10-08T18-13-23-696Z; static reviewed runtime hashes in production.
const proxyCode =
  ''
const implementationCode =
  ''
// GHO code: actual74 native original IDs57/70 (8046 bytes), independently approved keccak dd5142…0172.
const ghoCode =
  ''
const NOW = Date.parse('2026-10-08T18:00:00.000Z')
const owner = '0x1234567890123456789012345678901234567890'
const source = {
  chainId: 1 as const,
  blockNumber: 26149326,
  blockHash: '0x' + 'a'.repeat(64),
  blockTime: new Date(NOW - 60000).toISOString(),
  finalized: true as const,
}
const binding: UmbrellaGhoNativeCapacityBinding = {
  routeKey: UMBRELLA_GHO_ROUTE,
  destination: UMBRELLA_STKGHO,
  owner,
  asset: ORIGINAL_GHO,
  assetDecimals: 18,
  shareDecimals: 18,
  source,
  asOfMs: NOW,
}
const at = BigInt(Date.parse(source.blockTime) / 1000)
function fixture(
  options: {
    snapshot?: bigint
    end?: bigint
    window?: bigint
    paused?: boolean
    max?: bigint
    slash?: bigint
    assetDecimals?: number
    shareDecimals?: number
  } = {},
) {
  const S = 100n,
    CS = options.snapshot ?? 40n,
    end = options.end ?? at,
    window = options.window ?? 20n,
    paused = options.paused ?? false
  const open = CS > 0n && at >= end && at <= end + window
  const max = options.max ?? (paused ? 0n : open ? CS : 0n)
  const plan = [
    ...umbrellaGhoNativeCapacityReadPlan(owner, source),
    ...umbrellaGhoNativeCapacityEntitlementReadPlan(String(S), String(CS), source),
  ]
  return {
    readAtUtc: new Date(NOW - 1000).toISOString(),
    traces: plan.map((spec) => {
      let result: unknown
      if (spec.key.startsWith('header_'))
        result = {
          number: '0x' + source.blockNumber.toString(16),
          hash: source.blockHash,
          timestamp: '0x' + at.toString(16),
        }
      else if (spec.key === 'chain') result = '0x1'
      else if (spec.key.startsWith('code:'))
        result = spec.key.endsWith(UMBRELLA_STKGHO)
          ? proxyCode
          : spec.key.endsWith(VERIFIED_STKGHO_IMPLEMENTATION)
            ? implementationCode
            : ghoCode
      else if (spec.key === 'implementation_slot')
        result = '0x' + '0'.repeat(24) + VERIFIED_STKGHO_IMPLEMENTATION.slice(2)
      else {
        const data = (spec.request.params[0] as { data: `0x${string}` }).data
        const call = decodeFunctionData({ abi: UMBRELLA_GHO_NATIVE_ABI, data })
        let value: unknown
        switch (spec.key) {
          case 'asset':
            value = ORIGINAL_GHO
            break
          case 'asset_decimals':
            value = options.assetDecimals ?? 18
            break
          case 'share_decimals':
            value = options.shareDecimals ?? 18
            break
          case 'paused':
            value = paused
            break
          case 'full_shares':
            value = S
            break
          case 'total_assets':
            value = 1000n
            break
          case 'total_supply':
            value = 500n
            break
          case 'cooldown':
            value = 1728000n
            break
          case 'global_window':
            value = 172800n
            break
          case 'snapshot':
            value = [CS, Number(end), Number(window)]
            break
          case 'max_redeem':
            value = max
            break
          case 'slashable':
            value = options.slash ?? 0n
            break
          case 'cash':
            value = 800n
            break
          case 'full_ea':
          case 'snapshot_ea':
            value = (call.args![0] as bigint) * 2n
            break
          default:
            throw Error('fixture_key')
        }
        result = encodeFunctionResult({
          abi: UMBRELLA_GHO_NATIVE_ABI,
          functionName: call.functionName,
          result: value,
        } as never)
      }
      return { ...spec, result }
    }),
  }
}
function replay(wire = fixture(), b = binding) {
  return replayUmbrellaGhoNativeCapacityFact(wire, b)
}
describe('Umbrella native capacity raw replay (synthetic getters, unsigned)', () => {
  it('retains independent full S/Ea and partial cooldown shares/Ea in distinct units', () => {
    const fact = replay()!
    expect(fact).not.toBeNull()
    expect([
      fact.fullSharesRaw,
      fact.fullEaRaw,
      fact.cooldownSharesRaw,
      fact.cooldownSnapshotEaRaw,
      fact.maxRedeemSharesRaw,
    ]).toEqual(['100', '200', '40', '80', '40'])
    expect(fact.state).toBe('window_open')
    expect(fact.cooldownStartedAt).toBeNull()
    expect(fact.MRaw).toBeNull()
    expect(fact).not.toHaveProperty('maxWithdrawAssetsRaw')
    expect(fact).not.toHaveProperty('requestedRaw')
  })
  it('Q cannot alter full shares or entitlement', () => {
    const a = replay(fixture(), {
      ...binding,
      requestedRaw: '1',
    } as UmbrellaGhoNativeCapacityBinding)
    const b = replay(fixture(), {
      ...binding,
      requestedRaw: '999999999',
    } as UmbrellaGhoNativeCapacityBinding)
    expect(a).toEqual(b)
    expect(a?.fullEaRaw).toBe('200')
  })
  it('replays the approved actual GHO runtime without granting acquisition authority to facts or clones', () => {
    const fact = replay()!
    expect(fact.runtimeProfileQualified).toBe(true)
    expect(fact.runtimeCodeHashes[ORIGINAL_GHO]).toBe(
      '0xdd51428dd1ef13362e52bfc1689ed8e011730e6c6d5b50aaf96165ccd7bf0172',
    )
    expect(fact.qualification).toBe('runtime_profile_qualified')
    expect(selectedUmbrellaGhoNativeCapacityFact(fact, binding)?.originalAuthority).toBe(false)
    expect(
      selectedUmbrellaGhoNativeCapacityFact(structuredClone(fact), binding)?.originalAuthority,
    ).toBe(false)
    expect(
      selectedUmbrellaGhoNativeCapacityFact({ ...fact, originalAuthority: true }, binding),
    ).toBeNull()
    expect([
      fact.originalAuthority,
      fact.authenticated,
      fact.executionAuthority,
      fact.historicalOwnership,
      fact.guaranteedDelivery,
    ]).toEqual([false, false, false, false, false])
    expect(
      replayUmbrellaGhoNativeCapacityFact(
        { ...fixture(), originalAuthority: true, authenticated: true },
        binding,
      )?.originalAuthority,
    ).toBe(false)
  })
  it('uses inclusive maturity and inclusive expiry, with unopened/waiting/expired controls', () => {
    expect(replay(fixture({ snapshot: 0n, end: 0n, window: 0n }))?.state).toBe(
      'cooldown_not_started',
    )
    expect(replay(fixture({ end: at + 1n }))?.state).toBe('waiting')
    expect(replay(fixture({ end: at }))?.state).toBe('window_open')
    expect(replay(fixture({ end: at - 20n, window: 20n }))?.state).toBe('window_open')
    expect(replay(fixture({ end: at - 21n, window: 20n }))?.state).toBe('window_expired')
    expect(replay(fixture({ paused: true }))?.state).toBe('paused')
  })
  it('rejects an asset amount masquerading as maxRedeem share units', () => {
    expect(replay(fixture({ max: 80n }))).toBeNull()
    expect(replay(fixture({ max: 101n }))).toBeNull()
    expect(replay(fixture({ snapshot: 101n }))).toBeNull()
  })
  it('requires both paused native getters to return zero, preserving an expired oversized snapshot', () => {
    expect(replay(fixture({ paused: true, max: 40n }))).toBeNull()
    expect(replay(fixture({ paused: true, slash: 1n }))).toBeNull()
    expect(replay(fixture({ paused: true, max: 0n, slash: 0n }))?.state).toBe('paused')
    const expired = replay(fixture({ snapshot: 101n, end: at - 21n, window: 20n, max: 0n }))!
    expect(expired).not.toBeNull()
    expect(expired.state).toBe('window_expired')
    expect(expired.cooldownSharesRaw).toBe('101')
    expect(expired.fullSharesRaw).toBe('100')
  })
  it('zero slashable assets is not guaranteed delivery or a future amount', () => {
    const fact = replay(fixture({ slash: 0n }))!
    expect(fact.maxSlashableAssetsRaw).toBe('0')
    expect(fact.guaranteedDelivery).toBe(false)
    expect(fact.executionAuthority).toBe(false)
    expect(replay(fixture({ slash: 5n }))?.fullEaRaw).toBe('200')
  })
  it('rejects wrong native identity, runtime, slot and enclosing header', () => {
    for (const key of [
      'asset',
      'code:' + ORIGINAL_GHO,
      'code:' + UMBRELLA_STKGHO,
      'code:' + VERIFIED_STKGHO_IMPLEMENTATION,
      'implementation_slot',
      'header_after',
    ]) {
      const w = fixture(),
        t = w.traces.find((t) => t.key === key)!
      if (key === 'asset')
        t.result = encodeFunctionResult({
          abi: UMBRELLA_GHO_NATIVE_ABI,
          functionName: 'asset',
          result: owner,
        })
      else if (key === 'header_after') (t.result as { hash: string }).hash = '0x' + 'b'.repeat(64)
      else t.result = key === 'implementation_slot' ? '0x' + '0'.repeat(64) : '0x6000'
      expect(replay(w), key).toBeNull()
    }
    expect(replay(fixture({ assetDecimals: 6 }))).toBeNull()
    expect(replay(fixture({ shareDecimals: 6 }))).toBeNull()
  })
  it('rejects wrong full-position calldata, noncanonical ABI and reordered raw calls', () => {
    const wrong = fixture(),
      full = wrong.traces.find((t) => t.key === 'full_ea')!,
      snap = wrong.traces.find((t) => t.key === 'snapshot_ea')!
    full.request = snap.request
    expect(replay(wrong)).toBeNull()
    const noncanonical = fixture()
    noncanonical.traces.find((t) => t.key === 'full_ea')!.result =
      String(noncanonical.traces.find((t) => t.key === 'full_ea')!.result) + '00'
    expect(replay(noncanonical)).toBeNull()
    const reordered = fixture()
    ;[reordered.traces[0], reordered.traces[1]] = [reordered.traces[1], reordered.traces[0]]
    expect(replay(reordered)).toBeNull()
  })
  it('rejects future, negative, stale and noncanonical issue/read clocks', () => {
    expect(replay(fixture(), { ...binding, asOfMs: -1 })).toBeNull()
    expect(replay(fixture(), { ...binding, asOfMs: Date.parse(source.blockTime) - 1 })).toBeNull()
    expect(
      replay(fixture(), { ...binding, asOfMs: Date.parse(source.blockTime) + 1800001 }),
    ).toBeNull()
    const future = fixture()
    future.readAtUtc = new Date(NOW + 1).toISOString()
    expect(replay(future)).toBeNull()
    const before = fixture()
    before.readAtUtc = new Date(Date.parse(source.blockTime) - 1).toISOString()
    expect(replay(before)).toBeNull()
    const malformed = fixture()
    malformed.readAtUtc = '2026-10-08T17:59:59Z'
    expect(replay(malformed)).toBeNull()
  })
  it('rejects route, source units, getter accessors and cyclic inputs without invoking callers', () => {
    expect(replay(fixture(), { ...binding, routeKey: 'other' })).toBeNull()
    expect(replay(fixture(), { ...binding, asset: owner })).toBeNull()
    let calls = 0
    const accessor = {
      get readAtUtc() {
        calls++
        return new Date(NOW).toISOString()
      },
      traces: fixture().traces,
    }
    expect(replayUmbrellaGhoNativeCapacityFact(accessor, binding)).toBeNull()
    expect(calls).toBe(0)
    const cycle: Record<string, unknown> = {}
    cycle.self = cycle
    expect(replayUmbrellaGhoNativeCapacityFact(cycle, binding)).toBeNull()
  })
})

