describe('Umbrella native header projection', () => {
  it('accepts the actual 26-field, 93-transaction header while keeping only identity fields', () => {
    expect(actual93TransactionHeader.transactions).toHaveLength(93)
    const projected = projectUmbrellaGhoNativeHeader(actual93TransactionHeader)!
    expect(projected).toEqual({
      number: actual93TransactionHeader.number,
      hash: actual93TransactionHeader.hash,
      timestamp: actual93TransactionHeader.timestamp,
    })
    expect(Object.keys(projected)).toEqual(['number', 'hash', 'timestamp'])
    const s = {
      ...source,
      blockNumber: Number(BigInt(projected.number)),
      blockHash: projected.hash,
      blockTime: new Date(Number(BigInt(projected.timestamp)) * 1000).toISOString(),
    }
    const clock = Date.parse(s.blockTime),
      w = fixture()
    w.readAtUtc = new Date(clock + 1000).toISOString()
    for (const trace of w.traces) {
      if (trace.key.startsWith('header_')) {
        trace.request.params = ['0x' + s.blockNumber.toString(16), false]
        trace.result = actual93TransactionHeader
      } else if (trace.key !== 'chain')
        (trace.request.params as unknown[])[trace.request.params.length - 1] = {
          blockHash: s.blockHash,
          requireCanonical: true,
        }
      if (trace.key === 'snapshot')
        trace.result = encodeFunctionResult({
          abi: UMBRELLA_GHO_NATIVE_ABI,
          functionName: 'getStakerCooldown',
          result: [40n, Number(BigInt(projected.timestamp)), 20],
        })
    }
    const b = { ...binding, source: s, asOfMs: clock + 2000 }
    const fact = replayUmbrellaGhoNativeCapacityFact(w, b)!
    expect(fact).not.toBeNull()
    expect(fact.traces[0].result).toEqual(projected)
    expect(fact.fullEaRaw).toBe('200')
    expect(fact.originalAuthority).toBe(false)
    expect(
      replayUmbrellaGhoNativeCapacityFact(w, {
        ...b,
        source: { ...s, blockHash: '0x' + 'b'.repeat(64) },
      }),
    ).toBeNull()
  })
  it('rejects huge identity strings before native integer conversion', () => {
    for (const key of ['number', 'timestamp', 'hash']) {
      expect(
        projectUmbrellaGhoNativeHeader({
          ...actual93TransactionHeader,
          [key]: '0x' + 'f'.repeat(262145),
        }),
      ).toBeNull()
    }
    expect(
      projectUmbrellaGhoNativeHeader({ ...actual93TransactionHeader, number: '0x20000000000000' }),
    ).toBeNull()
  })
  it('rejects own accessors, symbols, exotic prototypes and noncanonical identity without invoking getters', () => {
    let reads = 0
    const accessor = { ...actual93TransactionHeader }
    Object.defineProperty(accessor, 'transactions', {
      enumerable: true,
      get() {
        reads++
        return []
      },
    })
    expect(projectUmbrellaGhoNativeHeader(accessor)).toBeNull()
    expect(reads).toBe(0)
    const identityAccessor = { ...actual93TransactionHeader }
    Object.defineProperty(identityAccessor, 'number', {
      enumerable: true,
      get() {
        reads++
        return actual93TransactionHeader.number
      },
    })
    const w = fixture()
    w.traces[0].result = identityAccessor
    expect(replay(w)).toBeNull()
    expect(reads).toBe(0)
    expect(
      projectUmbrellaGhoNativeHeader({ ...actual93TransactionHeader, [Symbol('hidden')]: 1 }),
    ).toBeNull()
    expect(
      projectUmbrellaGhoNativeHeader(Object.assign(Object.create({}), actual93TransactionHeader)),
    ).toBeNull()
    expect(
      projectUmbrellaGhoNativeHeader({ ...actual93TransactionHeader, number: '0x018f020e' }),
    ).toBeNull()
    expect(
      projectUmbrellaGhoNativeHeader({ ...actual93TransactionHeader, hash: '0x00' }),
    ).toBeNull()
  })
})
